      await win.locator('.arcade-canvas').screenshot({ path: path.join(outDir, `06-${inst}-erros.png`) });
      await win.getByRole('button', { name: 'Parar' }).click();
      await win.waitForTimeout(200);
      const d = win.getByRole('dialog');
      if (await d.count()) await d.getByRole('button', { name: 'Fechar' }).click();
    }
  } finally {
    console.log(errors.length ? 'FALHOU: ' + errors.join(' | ') : 'ok: sem erros na tela');
    await app.close();
  }
})().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});

