import sys
root = sys.argv[1]
p = root + '/apps/desktop/src/renderer/components/ArcadeStageCanvas.tsx'
s = open(p, encoding='utf-8').read()


def rep(a, b):
    global s
    assert s.count(a) == 1, a[:70]
    s = s.replace(a, b)


rep("import type { FofHighwayEngine, HighwayNote } from '@domain';",
    "import type { FofHighwayEngine, HighwayNote } from '@domain';\nimport stageBgUrl from '../assets/stage-bg.jpg';")

# --- background photo, loaded once; the drawn set is the fallback while it loads
rep("/** Cenário fixo (fundo do palco) desenhado uma vez por tamanho. */\nfunction paintSet(W: number, H: number, horizon: number): HTMLCanvasElement {",
    """/** Foto do palco (fundo da esteira): carregada uma vez; até chegar, vale o cenário desenhado. */
let stageBg: HTMLImageElement | null = null;
let stageBgReady = false;
function loadStageBg(onReady: () => void): void {
  if (stageBgReady) return;
  if (!stageBg) {
    stageBg = new Image();
    stageBg.src = stageBgUrl;
  }
  if (stageBg.complete && stageBg.naturalWidth > 0) {
    stageBgReady = true;
    return;
  }
  stageBg.addEventListener(
    'load',
    () => {
      stageBgReady = true;
      onReady();
    },
    { once: true },
  );
}

/** Foto de fundo cobrindo o painel (centrada), escurecida embaixo para a esteira ficar legível. */
function paintPhoto(W: number, H: number): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(W));
  c.height = Math.max(1, Math.round(H));
  const g = c.getContext('2d')!;
  const img = stageBg!;
  const scale = Math.max(W / img.naturalWidth, H / img.naturalHeight);
  const sw = W / scale;
  const sh = H / scale;
  g.drawImage(img, (img.naturalWidth - sw) / 2, img.naturalHeight - sh - (img.naturalHeight - sh) * 0.25, sw, sh, 0, 0, W, H);
  const shade = g.createLinearGradient(0, 0, 0, H);
  shade.addColorStop(0, 'rgba(5,3,12,0.25)');
  shade.addColorStop(0.5, 'rgba(5,3,12,0.35)');
  shade.addColorStop(1, 'rgba(5,3,12,0.8)');
  g.fillStyle = shade;
  g.fillRect(0, 0, W, H);
  return c;
}

/** Cenário fixo (fundo do palco) desenhado uma vez por tamanho. */
function paintSet(W: number, H: number, horizon: number): HTMLCanvasElement {""")

rep("""      const key = `${Math.round(W)}x${Math.round(H)}`;
      if (!set || setKey !== key) {
        set = paintSet(W, H, horizon);
        setKey = key;
      }""", """      loadStageBg(() => (setKey = ''));
      const key = `${Math.round(W)}x${Math.round(H)}${stageBgReady ? 'p' : 'd'}`;
      if (!set || setKey !== key) {
        set = stageBgReady ? paintPhoto(W, H) : paintSet(W, H, horizon);
        setKey = key;
      }""")
# the photo already has lights: soften the moving beams
rep("const alpha = 0.1 + 0.1 * intensity + 0.16 * pulse;", "const alpha = (0.1 + 0.1 * intensity + 0.16 * pulse) * (stageBgReady ? 0.6 : 1);")

# --- the highway as a 3D fretboard
a = s.index("      /* ------------------------------ pista ------------------------------ */")
b = s.index("      /* ------------------------------ notas ------------------------------ */")
neck = open(sys.argv[2], encoding='utf-8').read()
s = s[:a] + neck + s[b:]
open(p, 'w', encoding='utf-8').write(s)
print('ok')

