import { useState } from 'react';
import { readStore, writeStore } from '../lib/store.js';

export interface Profile {
  id: string;
  name: string;
  instrument: 'bass' | 'guitar' | 'keyboard';
  createdAt: string;
}
const KEY = 'bf-profiles';
const ACTIVE = 'bf-profile';
const DEFAULT: Profile = { id: 'p1', name: 'Músico', instrument: 'bass', createdAt: new Date(0).toISOString() };

export function readProfiles(): Profile[] {
  const l = readStore<Profile[]>(KEY, []);
  return l.length ? l : [DEFAULT];
}
export function activeProfile(): Profile {
  const id = readStore<string>(ACTIVE, 'p1');
  return readProfiles().find((p) => p.id === id) ?? readProfiles()[0]!;
}

/** Cada músico tem o próprio histórico: ao trocar, o histórico atual é guardado e o do outro é carregado. */
function switchTo(from: string, to: string) {
  if (from === to) return;
  writeStore(`bf-history:${from}`, readStore<unknown[]>('bf-history', []));
  writeStore('bf-history', readStore<unknown[]>(`bf-history:${to}`, []));
  writeStore(ACTIVE, to);
}

const LABEL = { bass: 'Contrabaixo', guitar: 'Guitarra', keyboard: 'Teclado' } as const;

export function Profiles({ onChanged }: { onChanged(): void }) {
  const [list, setList] = useState(readProfiles);
  const [active, setActive] = useState(() => activeProfile().id);
  const [name, setName] = useState('');
  const [instrument, setInstrument] = useState<Profile['instrument']>('bass');

  function pick(id: string) {
    switchTo(active, id);
    setActive(id);
    onChanged();
  }
  function add() {
    const n = name.trim();
    if (!n) return;
    const p: Profile = { id: `p${Date.now().toString(36)}`, name: n.slice(0, 40), instrument, createdAt: new Date().toISOString() };
    const next = [...list, p];
    writeStore(KEY, next);
    setList(next);
    setName('');
    pick(p.id);
  }
  return (
    <div className="screen">
      <header className="page-head">
        <h1>Músicos</h1>
        <p className="muted">Cada músico tem o próprio histórico, XP e progresso nas trilhas.</p>
      </header>
      <div className="profile-grid">
        {list.map((p) => (
          <section key={p.id} className={`card profile ${p.id === active ? 'on' : ''}`}>
            <span className="home-avatar" aria-hidden="true">
              {p.name.slice(0, 1).toUpperCase()}
            </span>
            <b>{p.name}</b>
            <span className="muted small">{LABEL[p.instrument]}</span>
            <button className={p.id === active ? 'ghost' : 'primary'} disabled={p.id === active} onClick={() => pick(p.id)}>
              {p.id === active ? 'Ativo' : 'Usar este músico'}
            </button>
          </section>
        ))}
      </div>
      <section className="card profile-new">
        <h3>Cadastrar músico</h3>
        <div className="profile-form">
          <input type="text" value={name} placeholder="Nome" maxLength={40} onChange={(e) => setName(e.target.value)} aria-label="Nome" />
          <select value={instrument} onChange={(e) => setInstrument(e.target.value as Profile['instrument'])} aria-label="Instrumento principal">
            <option value="bass">Contrabaixo</option>
            <option value="guitar">Guitarra</option>
            <option value="keyboard">Teclado</option>
          </select>
          <button className="primary" onClick={add} disabled={!name.trim()}>
            Cadastrar
          </button>
        </div>
      </section>
    </div>
  );
}

const MODULES = {
  theory: { title: 'Teoria musical & leitura', items: ['Intervalos', 'Formação de acordes', 'Leitura rítmica', 'Leitura de partitura'] },
  ear: { title: 'Laboratório prático & ear training', items: ['Percepção de intervalos', 'Reconhecimento de acordes', 'Ditado melódico', 'Ditado rítmico'] },
} as const;

/** Módulos da Academia: estrutura pronta para receber o conteúdo. */
export function Academy({ module }: { module: keyof typeof MODULES }) {
  const m = MODULES[module];
  return (
    <div className="screen">
      <header className="page-head">
        <h1>{m.title}</h1>
        <p className="muted">Módulo teórico · em breve</p>
      </header>
      <div className="trails-grid">
        {m.items.map((i) => (
          <section key={i} className="card trail">
            <h3>{i}</h3>
            <p className="muted small">Em breve</p>
          </section>
        ))}
      </div>
    </div>
  );
}

