import { clickAt, masterBus, pluckAt, setBassTimbre } from './practice.js';
import { playMidis, stopAll, type Timbre } from './harmonyAudioEngine.js';

const VOICE: Record<Exclude<EarTimbre, 'bass'>, Timbre> = { piano: 'piano', rhodes: 'rhodes', guitar: 'guitar' };

export interface PlayHandle {
  /** Duração total em segundos. */
  readonly seconds: number;
  cancel(): void;
}

/**
 * Toca os eventos com o timbre pedido (relógio único: tudo agendado no mesmo AudioContext).
 * `onNote` avisa quando cada nota começa, para acender o palco no tempo certo.
 */
export function playEvents(events: readonly EarEvent[], bpm: number, timbre: EarTimbre, onNote?: (midis: readonly number[]) => void, drone?: number): PlayHandle {
  const ctx = getAudioContext();
  void ctx.resume();
  stopAll();
  const t0 = ctx.currentTime + 0.06;
  const beat = 60 / bpm;
  const timers: number[] = [];
  let end = 0;
  const out = masterBus();
  for (const ev of events) {
    const at = t0 + ev.at * beat;
    const dur = ev.dur;
    end = Math.max(end, ev.at * beat + dur);
    if (ev.click) clickAt(at, ev.click === 'accent', 0.7, out);
    if (!ev.midis.length) continue;
    if (timbre === 'bass') {
      setBassTimbre('jazz');
      ev.midis.forEach((m, i) => pluckAt(at + i * 0.012, m >= 48 ? m - 12 : m, 0.85, out, Math.max(0.4, dur)));
    } else playMidis([...ev.midis], VOICE[timbre], at, Math.max(0.3, dur));
    if (onNote) timers.push(window.setTimeout(() => onNote(ev.midis), Math.max(0, (at - ctx.currentTime) * 1000)));
  }
  if (drone !== undefined) {
    setBassTimbre('jazz');
    for (let t = 0; t < end; t += 2.4) pluckAt(t0 + t, drone, 0.45, out, 2.6);
  }
  return {
    seconds: end + 0.1,
    cancel() {
      timers.forEach(clearTimeout);
      stopAll();
    },
  };
}

/** Toca uma única nota (resposta do usuário ao clicar no palco). */
export function playOne(midi: number, timbre: EarTimbre): void {
  playEvents([{ at: 0, midis: [midi], dur: 0.8 }], 60, timbre);
}

import { useCallback, useEffect, useState } from 'react';
import { levelProgress } from '@domain';
import { call, loadUsers, type DbUser } from '../lib/db.js';

/** Barra de XP no topo: nível, título e progresso do músico ativo (atualiza a cada ganho de XP). */
export function XpBar({ onOpen }: { onOpen(): void }) {
  const [user, setUser] = useState<DbUser | null>(null);
  const refresh = useCallback(() => {
    void loadUsers()
      .then((r) => setUser(r.users.find((u) => u.id === r.active) ?? null))
      .catch(() => undefined);
  }, []);
  useEffect(() => {
    refresh();
    window.addEventListener('bf-xp', refresh);
    return () => window.removeEventListener('bf-xp', refresh);
  }, [refresh]);
  useEffect(() => {
    // Confere conquistas ao abrir (por exemplo, nível 10 ou sequência de dias).
    void loadUsers().then((r) => call('achievements.check', { userId: r.active })).catch(() => undefined);
  }, []);
  if (!user) return null;
  const lv = levelProgress(user.total_xp);
  return (
    <button className="xpbar" onClick={onOpen} title="Ver conquistas e missões" aria-label={`Nível ${lv.level}, ${lv.title}, ${user.total_xp} XP`}>
      <span className="xpbar-level">Nível {lv.level}</span>
      <span className="xpbar-title">{lv.title}</span>
      <span className="xpbar-track" role="progressbar" aria-valuenow={Math.round(lv.fraction * 100)} aria-valuemin={0} aria-valuemax={100}>
        <span style={{ width: `${Math.round(lv.fraction * 100)}%` }} />
      </span>
      <span className="xpbar-xp">{user.total_xp} XP</span>
    </button>
  );
}

import { describe, expect, it } from 'vitest';
import { QUEST_POOL, comboMultiplier, dailyQuests, earXp, levelProgress, practiceXp, xpForLevel } from '../src/index.js';

describe('gamificação', () => {
  it('níveis 1 a 100 com títulos', () => {
    expect(levelProgress(0).level).toBe(1);
    expect(levelProgress(0).title).toBe('Iniciante de Garagem');
    expect(levelProgress(xpForLevel(10)).title).toBe('Sideman');
    expect(levelProgress(xpForLevel(100)).level).toBe(100);
    expect(levelProgress(xpForLevel(100)).title).toBe('Maestro mixerCraft');
    expect(levelProgress(xpForLevel(100) * 3).fraction).toBe(1);
  });
  it('combo e XP', () => {
    expect([1, 3, 6, 10].map(comboMultiplier)).toEqual([1, 2, 3, 5]);
    expect(earXp(10)).toBe(75);
    expect(practiceXp(0)).toBeGreaterThanOrEqual(50);
    expect(practiceXp(100)).toBeLessThanOrEqual(150);
    expect(practiceXp(95)).toBeGreaterThan(practiceXp(85));
  });
  it('3 missões distintas e estáveis por dia', () => {
    const a = dailyQuests('2026-11-17');
    expect(a).toHaveLength(3);
    expect(new Set(a.map((q) => q.code)).size).toBe(3);
    expect(dailyQuests('2026-11-17')).toEqual(a);
    for (const q of a) expect(QUEST_POOL).toContain(q);
  });
});

